#include <stdio.h>

int main()
{
    char s[105];
    int i = 0, letter = 0, digit = 0, other = 0;
    scanf("%s", s);
    while (s[i] != '\0')
    {
        if ((s[i] >= 'a' && s[i] <= 'z') || (s[i] >= 'A' && s[i] <= 'Z'))
            letter++;
        else if (s[i] >= '0' && s[i] <= '9')
            digit++;
        else
            other++;
        i++;
    }
    printf("%d\n", letter);
    printf("%d\n", digit);
    printf("%d\n", other);
    return 0;
}

#include <stdio.h>

int main()
{
    int n, i, j, k = 0, dup, a[100], b[100];
    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    for (i = 0; i < n; i++)
    {
        dup = 0;
        for (j = 0; j < k; j++)
            if (b[j] == a[i])
            {
                dup = 1;
                break;
            }
        if (!dup)
        {
            b[k] = a[i];
            k++;
        }
    }
    printf("%d\n", k);
    for (i = 0; i < k; i++)
    {
        if (i)
            printf(" ");
        printf("%d", b[i]);
    }
    printf("\n");
    return 0;
}

